class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        # 堆里放 (值, 链表编号, 节点)，编号用来在值相等时比较
        heap = [(node.val, i, node) for i, node in enumerate(lists) if node]
        heapq.heapify(heap)
        dummy = cur = ListNode()
        while heap:
            val, i, node = heapq.heappop(heap)
            cur.next = node
            cur = node
            if node.next:
                heapq.heappush(heap, (node.next.val, i, node.next))
        return dummy.next

class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        def merge2(a, b):
            dummy = cur = ListNode()
            while a and b:
                if a.val <= b.val:
                    cur.next, a = a, a.next
                else:
                    cur.next, b = b, b.next
                cur = cur.next
            cur.next = a or b
            return dummy.next

        if not lists:
            return None
        while len(lists) > 1:
            lists = [merge2(lists[i], lists[i + 1] if i + 1 < len(lists) else None)
                     for i in range(0, len(lists), 2)]
        return lists[0]

class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        def walk(node):
            while node:
                yield node
                node = node.next
        dummy = tail = ListNode()
        for node in heapq.merge(*map(walk, lists), key=lambda n: n.val):
            tail.next = tail = node
        tail.next = None
        return dummy.next

